39	func usage() {
40		fmt.Println("usage: indexroom [demo|version|register|help]")
41		fmt.Println()
42		fmt.Println("register reads requests as JSON from standard input and maintains an")
43		fmt.Println("in-memory service instance registry with offline health observations:")
44		fmt.Println(`  {"requests":[{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"host:8080"}]},`)
45		fmt.Println(`              {"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":1,"healthy":true},`)
46		fmt.Println(`              {"type":"select","service":"svc","expectedRevision":1}]}`)
47		fmt.Println("A register request fully replaces the service's instance list; new services")
48		fmt.Println("require expectedRevision 0, existing services the current revision. A health")
49		fmt.Println("request records an offline observation (healthy/unhealthy) for one instance;")
50		fmt.Println("it never probes. Health updates never bump the registration revision. A")
51		fmt.Println("select request chooses one healthy instance, rotating per service by ascending")
52		fmt.Println("instance id; it performs no network access and never changes revisions or")
53		fmt.Println("health records, and reports invalid/conflict/not_found/no_healthy on failure.")
54		fmt.Println("A select request may carry an optional \"sessionKey\" string: requests in the")
55		fmt.Println("same service with the same trimmed key reuse the instance first chosen for")
56		fmt.Println("that key while it stays registered and healthy, without moving the rotation.")
57		fmt.Println("Exit status is 0 only when every request succeeds and the JSON result")
58		fmt.Println("is fully written to standard output. A failed result write is reported")
59		fmt.Println("on standard error with the underlying write error and also exits 1,")
60		fmt.Println("without appending a second JSON document to the partial output.")
61	}
62	
63	// registerInstance is one instance in the final service list.
64	type registerInstance struct {
65		ID       string `json:"id"`
66		Address  string `json:"address"`
67		Health   string `json:"health"`
68		Sequence int64  `json:"sequence"`
69		Reason   string `json:"reason,omitempty"`
70	}
71	
72	// registerService is one service in the final service list.
73	type registerService struct {
74		Service   string             `json:"service"`
75		Revision  int                `json:"revision"`
76		Instances []registerInstance `json:"instances"`
77	}
78	
79	// registerResult is the per-item outcome.
80	type registerResult struct {
81		Service          string `json:"service"`
82		OK               bool   `json:"ok"`
83		Changed          bool   `json:"changed,omitempty"`
84		Revision         int    `json:"revision"`
85		Error            string `json:"error,omitempty"`
86		Reason           string `json:"reason,omitempty"`
87		ExpectedRevision int    `json:"expectedRevision,omitempty"`
88		ActualRevision   int    `json:"actualRevision,omitempty"`
89		Sequence         int64  `json:"sequence,omitempty"`
90		InstanceID       string `json:"instanceId,omitempty"`
91		Address          string `json:"address,omitempty"`
92	}
93	
94	// registerOutput is the full register output.
95	type registerOutput struct {
96		Results  []registerResult  `json:"results"`
97		Services []registerService `json:"services"`
98	}
99	
100	// runRegister processes registration requests from the process standard
101	// streams. It returns the process exit code: 0 when all registrations succeed
102	// and the result is fully written, 1 otherwise.
103	func runRegister() int {
104		return runRegisterIO(os.Stdin, os.Stdout, os.Stderr)
105	}
106	
107	// runRegisterIO is runRegister with injectable streams. in supplies the JSON
108	// request batch, out receives the single JSON result document and errOut
109	// receives diagnostics (in particular a result-delivery failure, which must
110	// never be mixed into out).
111	func runRegisterIO(in io.Reader, out io.Writer, errOut io.Writer) int {
112		data, err := io.ReadAll(in)
113		if err != nil {
114			return failRegister(out, errOut, fmt.Sprintf("could not read standard input: %v", err))
115		}
116	
117		var top struct {
118			Requests json.RawMessage `json:"requests"`
119		}
120		if err := json.Unmarshal(data, &top); err != nil {
121			return failRegister(out, errOut, fmt.Sprintf("input must be a JSON object with a requests array: %v", err))
122		}
123		if len(top.Requests) == 0 || strings.TrimSpace(string(top.Requests)) == "null" {
124			return failRegister(out, errOut, "input must contain a \"requests\" array")
125		}
126		var rawRequests []json.RawMessage
127		if err := json.Unmarshal(top.Requests, &rawRequests); err != nil {
128			return failRegister(out, errOut, "\"requests\" must be a JSON array")
129		}
130	
131		proc := &registerProcessor{
132			registry: indexroom.NewRegistry(),
133			results:  make([]registerResult, 0, len(rawRequests)),
134		}
135	
136		for _, raw := range rawRequests {
137			var head struct {
138				Service string          `json:"service"`
139				Type    json.RawMessage `json:"type"`
140			}
141			_ = json.Unmarshal(raw, &head)
142			service := strings.TrimSpace(head.Service)
143	
144			reqType := "register"
145			if len(head.Type) > 0 && strings.TrimSpace(string(head.Type)) != "null" {
146				var t string
147				if err := json.Unmarshal(head.Type, &t); err != nil {
148					proc.invalid(service, "type must be a string")
149					continue
150				}
151				reqType = t
152			}
153	
154			switch reqType {
155			case "", "register":
156				proc.registerRequest(raw, service)
157			case "health":
158				proc.healthRequest(raw, service)
159			case "select":
160				proc.selectRequest(raw, service)
161			default:
162				proc.invalidf(service, "unknown type %q", reqType)
163			}
164		}
165	
166		results, anyFailed := proc.results, proc.failed
167		registry := proc.registry
168	
169		services := make([]registerService, 0)
170		for _, view := range registry.Snapshot() {
171			insts := make([]registerInstance, 0, len(view.Instances))
172			for _, inst := range view.Instances {
173				insts = append(insts, registerInstance{
174					ID:       inst.ID,
175					Address:  inst.Address,
176					Health:   string(inst.Health),
177					Sequence: inst.Sequence,
178					Reason:   inst.Reason,
179				})
180			}
181			services = append(services, registerService{
182				Service:   view.Service,
183				Revision:  view.Revision,
184				Instances: insts,
185			})
186		}
187	
188		if err := writeRegisterOutput(out, registerOutput{Results: results, Services: services}); err != nil {
189			// The request results could not be delivered. This is independent of
190			// whether the requests themselves succeeded: the caller must be able to
191			// tell an undelivered result from a rejected request.
192			reportRegisterDeliveryFailure(errOut, err)
193			return 1
194		}
195		if anyFailed {
196			return 1
197		}
198		return 0
199	}
200	
201	// registerProcessor runs the request batch in input order. Failed items keep
202	// their slot in results and set failed; later items still run against the
203	// state committed by earlier successful items.
204	type registerProcessor struct {
205		registry *indexroom.Registry
206		results  []registerResult
207		failed   bool
208	}
209	
210	// invalid records an input-validation failure for an item. Content validity is
211	// checked before any business rule, so the revision stamped here is the
212	// service's current revision when the item is handled.
213	func (p *registerProcessor) invalid(service, reason string) {
214		p.failed = true
215		p.results = append(p.results, registerResult{
216			Service:  service,
217			OK:       false,
218			Error:    "invalid",
219			Reason:   reason,
220			Revision: p.registry.RevisionOf(service),
221		})
222	}
223	
224	// invalidf is invalid with a formatted reason.
225	func (p *registerProcessor) invalidf(service, format string, args ...any) {
226		p.invalid(service, fmt.Sprintf(format, args...))
227	}
228	
229	// parseRevision decodes the raw expectedRevision token for one request. An
230	// absent or explicitly null token is "required"; a token that is not a decimal
231	// integer is an integer-type invalid. A decimal integer is returned as int64 —
232	// still carrying the submitted value — so the registry can range-check it
233	// against the architecture (0..2147483647 on 32-bit, 0..9223372036854775807
234	// on 64-bit) before it is narrowed to int; narrowing first would wrap values
235	// like 4294967297 into 1 on a 32-bit build. It reports false after appending
236	// the item's invalid result, which stamps the service's current revision.
237	func (p *registerProcessor) parseRevision(service string, raw json.RawMessage) (int64, bool) {
238		if len(raw) == 0 || strings.TrimSpace(string(raw)) == "null" {
239			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
240			return 0, false
241		}
242		revision, err := indexroom.ParseExpectedRevision(string(raw))
243		if err != nil {
244			p.invalid(service, err.Error())
245			return 0, false
246		}
247		return revision, true
248	}
249	
250	// reject records a business-rule failure (conflict, not_found, stale or
251	// no_healthy), keeping each operation's distinct result fields. Health
252	// rejections additionally carry the current sequence; register and select
253	// pass 0 so it stays omitted.
254	func (p *registerProcessor) reject(service string, kind indexroom.OutcomeKind, reason string, revision, expected, actual int, sequence int64) {
255		p.failed = true
256		p.results = append(p.results, registerResult{
257			Service:          service,
258			OK:               false,
259			Error:            string(kind),
260			Reason:           reason,
261			Revision:         revision,
262			ExpectedRevision: expected,
263			ActualRevision:   actual,
264			Sequence:         sequence,
265		})
266	}
267	
268	// succeed records an accepted item; omitempty keeps zero-valued fields out of
269	// the output exactly as before the refactor.
270	func (p *registerProcessor) succeed(result registerResult) {
271		result.OK = true
272		p.results = append(p.results, result)
273	}
274	
275	// registerRequest processes one register request, appending its outcome.
276	func (p *registerProcessor) registerRequest(raw json.RawMessage, service string) {
277		var req struct {
278			Service   string          `json:"service"`
279			Revision  json.RawMessage `json:"expectedRevision"`
280			Instances json.RawMessage `json:"instances"`
281		}
282		if err := json.Unmarshal(raw, &req); err != nil {
283			p.invalidf(service, "request must be an object with service, expectedRevision and instances: %v", err)
284			return
285		}
286		service = strings.TrimSpace(req.Service)
287	
288		if len(req.Revision) == 0 || strings.TrimSpace(string(req.Revision)) == "null" {
289			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
290			return
291		}
292		if !isJSONArray(req.Instances) {
293			p.invalid(service, "instances must be an array")
294			return
295		}
296		var instances []indexroom.Instance
297		if err := json.Unmarshal(req.Instances, &instances); err != nil {
298			p.invalidf(service, "instances must be an array of objects with id and address: %v", err)
299			return
300		}
301	
302		// Parse the raw token (integer type); ValidateRegistration then range-checks
303		// the int64 against the architecture before narrowing it to int.
304		revision, ok := p.parseRevision(service, req.Revision)
305		if !ok {
306			return
307		}
308		registration, err := p.registry.ValidateRegistration(service, revision, instances)
309		if err != nil {
310			p.invalid(service, err.Error())
311			return
312		}
313	
314		outcome := p.registry.Apply(registration)
315		if !outcome.OK {
316			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
317			return
318		}
319		p.succeed(registerResult{
320			Service:  outcome.Service,
321			Changed:  outcome.Changed,
322			Revision: outcome.Revision,
323		})
324	}
325	
326	// healthRequest processes one health observation request, appending its outcome.
327	func (p *registerProcessor) healthRequest(raw json.RawMessage, service string) {
328		var req struct {
329			Service    string          `json:"service"`
330			InstanceID string          `json:"instanceId"`
331			Revision   json.RawMessage `json:"expectedRevision"`
332			Sequence   *int64          `json:"sequence"`
333			Healthy    *bool           `json:"healthy"`
334			Reason     *string         `json:"reason"`
335		}
336		if err := json.Unmarshal(raw, &req); err != nil {
337			p.invalidf(service, "health request must be an object with service, instanceId, expectedRevision, sequence and healthy: %v", err)
338			return
339		}
340		service = strings.TrimSpace(req.Service)
341	
342		if len(req.Revision) == 0 || strings.TrimSpace(string(req.Revision)) == "null" {
343			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
344			return
345		}
346		if req.Sequence == nil {
347			p.invalid(service, "sequence is required and must be a positive integer")
348			return
349		}
350		if req.Healthy == nil {
351			p.invalid(service, "healthy is required and must be a boolean")
352			return
353		}
354		reason := ""
355		if req.Reason != nil {
356			reason = *req.Reason
357		}
358	
359		// Parse the raw token (integer type); ValidateHealth then range-checks the
360		// int64 against the architecture before narrowing it to int.
361		revision, ok := p.parseRevision(service, req.Revision)
362		if !ok {
363			return
364		}
365		update, err := p.registry.ValidateHealth(service, req.InstanceID, revision, *req.Sequence, *req.Healthy, reason)
366		if err != nil {
367			p.invalid(service, err.Error())
368			return
369		}
370	
371		outcome := p.registry.ApplyHealth(update)
372		if !outcome.OK {
373			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, outcome.Sequence)
374			return
375		}
376		p.succeed(registerResult{
377			Service:  outcome.Service,
378			Changed:  outcome.Changed,
379			Revision: outcome.Revision,
380			Sequence: outcome.Sequence,
381		})
382	}
383	
384	// selectRequest processes one select request, appending its outcome.
385	// A selection performs no network access and never alters registrations or
386	// health records; it only advances the service's healthy-instance rotation
387	// and, for requests carrying a sessionKey, maintains that session's binding.
388	func (p *registerProcessor) selectRequest(raw json.RawMessage, service string) {
389		var req struct {
390			Service  string          `json:"service"`
391			Revision json.RawMessage `json:"expectedRevision"`
392			Session  json.RawMessage `json:"sessionKey"`
393		}
394		if err := json.Unmarshal(raw, &req); err != nil {
395			p.invalidf(service, "select request must be an object with service and expectedRevision: %v", err)
396			return
397		}
398		service = strings.TrimSpace(req.Service)
399	
400		if len(req.Revision) == 0 || strings.TrimSpace(string(req.Revision)) == "null" {
401			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
402			return
403		}
404	
405		// sessionKey is optional: absent means an ordinary rotating selection. An
406		// explicitly provided null, a non-string value or a blank string is
407		// invalid; the registry trims the key and treats keys equal after trimming
408		// as the same session.
409		var sessionKey *string
410		if len(req.Session) > 0 {
411			if strings.TrimSpace(string(req.Session)) == "null" {
412				p.invalid(service, "sessionKey must be a string, not null")
413				return
414			}
415			var key string
416			if err := json.Unmarshal(req.Session, &key); err != nil {
417				p.invalid(service, "sessionKey must be a string")
418				return
419			}
420			sessionKey = &key
421		}
422	
423		revision, ok := p.parseRevision(service, req.Revision)
424		if !ok {
425			return
426		}
427	
428		selection, err := p.registry.ValidateSelectionWithSession(service, revision, sessionKey)
429		if err != nil {
430			p.invalid(service, err.Error())
431			return
432		}
433	
434		outcome := p.registry.Select(selection)
435		if !outcome.OK {
436			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
437			return
438		}
439		p.succeed(registerResult{
440			Service:    outcome.Service,
441			Revision:   outcome.Revision,
442			InstanceID: outcome.InstanceID,
443			Address:    outcome.Address,
444			Sequence:   outcome.Sequence,
445		})
446	}
447	
448	// failRegister emits a top-level input error as the single JSON document on
449	// out and returns exit code 1. If that error JSON itself cannot be written,
450	// the delivery failure is diagnosed on errOut (out may already hold a partial
451	// document, so no second JSON is appended) and the exit code stays 1.
452	func failRegister(out io.Writer, errOut io.Writer, reason string) int {
453		if err := writeRegisterOutput(out, struct {
454			Error string `json:"error"`
455		}{Error: reason}); err != nil {
456			reportRegisterDeliveryFailure(errOut, err)
457		}
458		return 1
459	}
460	
461	// reportRegisterDeliveryFailure reports on errOut that the register command's
462	// JSON result could not be delivered, preserving the underlying write error.
463	// It never writes to standard output, which may already contain a partial
464	// result.
465	func reportRegisterDeliveryFailure(errOut io.Writer, err error) {
466		fmt.Fprintf(errOut, "register: failed to write request results to standard output: %v\n", err)
467	}
468	
469	// writeRegisterOutput writes v as the single indented JSON document on w.
470	// Standard output is dedicated to this document, so a write failure is returned
471	// instead of swallowed: the caller must not attempt to append another document
472	// after a partial write.
473	func writeRegisterOutput(w io.Writer, v any) error {
474		enc := json.NewEncoder(w)
475		enc.SetIndent("", "  ")
476		return enc.Encode(v)
477	}
478	
479	// isJSONArray reports whether raw is a JSON array (ignoring leading whitespace).
480	func isJSONArray(raw json.RawMessage) bool {
481		for _, b := range raw {
